CREATE TABLE IF NOT EXISTS school_presence_leases (user_id VARCHAR(32) NOT NULL,runtime_id VARCHAR(32) NOT NULL,tab_id VARCHAR(64) NOT NULL,session_version INTEGER NOT NULL,expires_at BIGINT NOT NULL,sequence BIGINT NOT NULL,discard_at BIGINT NOT NULL,PRIMARY KEY(user_id,runtime_id,tab_id),INDEX school_presence_runtime (runtime_id),INDEX school_presence_expiry (discard_at),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
